import DashboardLayout from "../layouts/DashboardLayout";

const permissions = {
  admin: ["Manage all campaigns", "Record and audit donations", "Coordinate volunteers", "View impact reporting"],
  staff: ["Manage assigned campaigns", "Record donor conversations", "Coordinate volunteer shifts"],
  volunteer: ["View assignments", "Update availability", "Support field activities"]
};

export default function Profile() {
  const user = JSON.parse(localStorage.getItem("user") || "null");
  const rolePermissions = permissions[user?.role] || permissions.volunteer;

  return (
    <DashboardLayout title="Profile" eyebrow="Account">
      <section className="profile-layout">
        <div className="card profile-card">
          <div className="avatar">{user?.name?.charAt(0) || "S"}</div>
          <h3>{user?.name || "Demo User"}</h3>
          <p>{user?.title || "Seva Foundation Team"}</p>
          <span className="status completed">{user?.role || "volunteer"}</span>
        </div>
        <div className="card">
          <h3>Portal Access</h3>
          <div className="permission-list">
            {rolePermissions.map((permission) => (
              <span key={permission}>{permission}</span>
            ))}
          </div>
        </div>
        <div className="card">
          <h3>Contact</h3>
          <p>{user?.email || "admin@sevafoundation.test"}</p>
          <p>Seva Foundation operating portal</p>
        </div>
      </section>
    </DashboardLayout>
  );
}
